BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (130::BIGINT, 'El profe es un poco intenso, pero todo mundo pasa con notas de 90 o asi, lo unico es que si hay que estar en todas con el proyecto, si hay algun problema con compañeros o asi el mae entiente y lo ayuda, pero debe decirle o sino puede que se le haga largo al final, lo recomiendo ~_~'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, '97a213c5712ca0151a9a89a824eefe204679eef9d2e57938619c1eff4537ad77'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'De los peores profes, el mae piensa que el mundo gira en él y se la suda las opiniones de otros. Deja trabajos de lecturas y presentaciones a montones como si solo tuviéramos clases con él.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, '487b827aa97a8415197214e0cd2dc63d8a24a2d094489b8b6fe7eaab9c2fa8fa'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'NO MATRICULE CON EL Habla según sus intereses (comunismo, anticapitalismo, etc.) nada relacionado con el curso, prácticamente no da materia y exige trabajos y presentaciones todas las semanas, en los que no hay rubricas ni un sentido al evaluar. Grita en clase, se enoja si no tienen internet (es el)'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2025-11-18T00:00:00+00:00'::TIMESTAMPTZ, '4a60e31df112c2051de5db143f5765a17c6bd43465a851a609b55c9ef7f574c1'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Simplemente el peor profesor. No solo del TEC, el peor profesor entre todos, preferiría clases de como hablar inglés de un mudo a otra clase con él.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'bc288ebf0c204091a09a8224ccc1dd936105588edce5a0014deb7b129336a9ec'::TEXT, ARRAY[3230]::BIGINT[]),
    (130::BIGINT, 'Es un resentido social'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-10T00:00:00+00:00'::TIMESTAMPTZ, '797a6d1dbc071b6394bf001dacac073ae8885c1a7093df582b4fc8b89a4d2f11'::TEXT, ARRAY[3230]::BIGINT[]),
    (130::BIGINT, 'No vale la pena llevar un curso con este mae. Deja lecturas eternas para cada clase, no necesariamente en español o inglés. Las clases las extiende 1 hora más del tiempo de finalización y si uno se sale a la hora, ausencia. No puedo escribir más, pero es el peor profesor de toda la U.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-10-10T00:00:00+00:00'::TIMESTAMPTZ, '1f0437a2f4d12b0f15a7a91a411ea88b8a8e67ca258aa756490f630f501ba4d8'::TEXT, ARRAY[3230]::BIGINT[]),
    (130::BIGINT, 'PÉSIMO PÉSIMO PÉSIMO! Un asco de profesor. No planifica las clases ni da porcentajes del valor de las evaluaciones, habla cosas muy irrelevantes en clase por lo cual la clase se termina extendiendo más allá del tiempo estipulado. De esos parásitos que sólo se meten en el TEC para cobrar sueldo.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-22T00:00:00+00:00'::TIMESTAMPTZ, '63d0fe766e1555e77c10df14b72caf1ae18a46d5618808be3c4195abb6325bd9'::TEXT, ARRAY[3230]::BIGINT[]),
    (130::BIGINT, 'Está en mi top 2 de peores profesores que he tenido en toda mi historia desde que estoy en el kinder, se gana el salario por absolutamente nada, porque no planifica el curso, toda la clase habla paja, no da instrucciones, no da cronograma, no da fechas, ni siquiera dice cuanto vale cada trabajo....'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2025-09-04T00:00:00+00:00'::TIMESTAMPTZ, 'd085d3e00244a201226cebda706b7027ff4727ca33c34a65d89c62a016939ac5'::TEXT, ARRAY[3230]::BIGINT[]),
    (130::BIGINT, 'Juep.curso mas malo... deberia ded8carse a otra cosa este señor pprque de peofe nada que ver'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-20T00:00:00+00:00'::TIMESTAMPTZ, '3725267b04b6375ccf64fb7fcd44c136d7b791ab89f88ae1a7e004e58196d722'::TEXT, ARRAY[1004, 3230]::BIGINT[]),
    (130::BIGINT, 'Lo llevé virtual en verano. No hay que encender la cámara, es específico y claro con lo que pide para los trabajos. Las entregas son largas PERO al ser grupales quedan fáciles de realizar si se dejan una pregunta cada uno, además califica suave. Se nota que tiene amor por lo que enseña.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2025-01-28T00:00:00+00:00'::TIMESTAMPTZ, '1ab7d313be005448a40aa31f6a91b35e3a5caad2cf566bb23a40077b20e2d0bd'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Si usted tiene un buen grupo de trabajo se pasa facil. Deja tareas y se exponen todas las semanas. Las clases si se suelen hacer largas pero a veces se sale temprano. Califica suave y es pura vida aunque cuesta que conteste correo o mensajes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dea4ab3120d033001159b4f41f8a20e4c1a817935977ed33a1b97b05bc142800'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Las clases son largas y aburridas como suelen ser los seminarios, casi que es él hablando todo el rato. Deja lecturas largas + tareas y exposiciones absolutamente todas las semanas y una investigación que también es larga, pero es muy fácil sacar buena nota porque califica súper suave.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '54b851198c907b1511f8e8c8cc6f04f1968a6f0828a1b18dbc2e2e00bd7e48e5'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'No recomendaría matricular con este profe por gusto, sino tiene alternativa no está tan mal, pero si puede escoger otro mejor. Por ser modalidad virtual y verano fue bastante llevadero y no califica duro, pero es aburrido.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-01-20T00:00:00+00:00'::TIMESTAMPTZ, '305fad89a949c561c8ebcbb1301d9a4cb1cd44d806b3f2f4501004f9d04c45ca'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Retiren el curso si matriculan con este profesor. Ni pierdan el tiempo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b776c32c96b1f13929b5994c13323aa88dbb4090ae101af27f678fe6de0a8ef4'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Es facil sacar una buena nota con el, sin embargo deja demasiados trabajos como si el curso fuera de mas creditos y las clases son muy aburridas, los temas que trata son confusos. Si quiere un curso ligero definitivamente el no es la opcion'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '51ebe39e15bd9dcffc4eacbfacbcf4192c023c23a38b8ce326a52ad56447741f'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Es un buen profe, se aprende muchísimo, es bastante exigente, TODO se trabaja en grupo, si no tiene un grupo que le pone pierde el curso, el curso está hecho para trabajarse en grupo, las lecturas son rudas pero interesantes y el proyecto final se trabaja desde semanas tempranas, curso RUDO.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, '487c4e2703b75fb2ab0d36a27eb8bbdef3205021be8a8e617a45ba8cb628ea7b'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Desorden en la planificación de las clases.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'cfb5527bd7856b5303dba2d97c9ec772f8a8c35c94a496da5a32059cda17cdbe'::TEXT, ARRAY[4518]::BIGINT[]),
    (130::BIGINT, 'No es claro con las instrucciones. Cuando se solicita de su ayuda no lo hace. Habla mucho, y como estudiante se participa poco. Aburridisimo Tiene mucho conocimiento.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'b8a04492be4a1e2d7d668f713ca0e832562e67f5f2b4715cc6c12334ac5c232b'::TEXT, ARRAY[3139]::BIGINT[]),
    (130::BIGINT, 'Pésimo profesor. Chancleta, juega de vivo, cree que tiene la verdad absoluta. No matricule con él, ni aunque sea el único que esté disponible.Por último, el curso se llama Seminario de Estudios costarricenses , sin embargo nunca se trato ningún tema de índole nacional.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'ffabd56d4f794f42f6f99063300d8ec35c13d406780116c4e3972ee03ad9b96e'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Pésimo. Mejor retiré el curso. Deja demasiados trabajos y se debe dedicar mucho tiempo al curso'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2019-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'd9bb5e796f05d5185979aca52d210a14c59aea21233955dd31167dd318a6ef7e'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Al chile no lleven con el.Ensayos toda la semana, le gusta que uno se vuelva chancleta y cree que es un curso de cuatro créditos.Nos mando larguísimo a hacer un proyecto el cual ni siquiera escogimos en primer lugar.Los temas los escogió el por qué la gente escogía cosas “que no eran relevantes”'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-11-08T00:00:00+00:00'::TIMESTAMPTZ, '60a83677dc57ef5d74741a0408f40cf3bc83d9053f8f7a0258dbd74e8a9431c5'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Es el peor profesor que he tenido en el TEC. Retiré el curso. Califica durísimo y no da rúbricas de evaluación. Usted simplemente no sabe cómo le gustan los ensayos. Llega tarde y si no va a clases no le avisa a los estudiantes, además de injusto con la calificación. Es una vergüenza para el TEC'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4ce030a655058f97748c9680905334bf452282a2d515e219516825593422bdfd'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Entré a esa clase porque no quedaba de otra. El profe lo ve como un curso de 4 créditos, hacer ensayo cada semana, son fáciles y si hace todos los ensayos buenos y los tres avances de proyectos bien pasa el curso. Para que el profe te importe es solo jugar de ambientalista nada más.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '783cdad16fec62e68319117cf06be5874977de06708ffe2f3d075f0f8405ac4c'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'd358a55302dcf247a51ff2601b66455268fe7af9ba20eb64f636cd32d0aeffcf'::TEXT, ARRAY[3134]::BIGINT[]),
    (130::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-25T00:00:00+00:00'::TIMESTAMPTZ, '6fb3c7dbd90a0bb4a9ad639bc14978feced9d3fc6acc76ee5598184d0ad2c5bc'::TEXT, ARRAY[3134]::BIGINT[]),
    (130::BIGINT, 'La clase es muy interesante, uno en serio aprende pero le exige como si el curso fuese de más créditos, para mí muy bien curso pero lecturas excesivas y no vale los créditos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd40c571b387c704e86af704b0d6301124d515a472b4b9a841ebf06b185114687'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'El curso es fácil pero quita mucho tiempo, deja en sayo todas las semanas con lecturas horribles. El curso quita mucho tiempo como si fuera de 4 créditos'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'db31abf4841e1df5df9ab587328f4e9d5368c4e00e4ca5600f91afa392518fc9'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'Quita demasiado tiempo para el curso que es. Deja lecturas y reportes todas las semanas (en su mayoría extensas) y exige demasiado esfuerzo y tiempo desde la semana 1. NO LO RECOMIENDO.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a2f661f1835e825563fd0ae106905ded9d7a9a4bfb38fdcd71631a5740dba70c'::TEXT, ARRAY[1004]::BIGINT[]),
    (130::BIGINT, 'La verdad es que para el curso que es, es un profesor que quita tiempo en exceso, sus lecturas ALGUNAS son muy extensas, sus trabajos de investigación son exhaustivos hasta el punto de tener que ir al lugar escogido para la investigación varias veces para hacer distintas cosas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2015-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'adfb8000e67eddd4b98d719ed0b9434823db43d285db559a693c042ce1b60f26'::TEXT, ARRAY[1004]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
